    "form",
    { onSubmit: handleSubmit, noValidate: true, ariaLabel: "Notification preferences" },
    FormField({
      options: NOTIFICATION_OPTIONS,
      selected,
      onChange: handleChange,
      error,
    }),
    createElement(
      "button",
      {
        type: "submit",
        className: "btn-submit",
        disabled: submitted,
        ariaDisabled: submitted ? "true" : "false",
      },
      submitted ? "✓ Saved" : "Save Preference"
    ),
    submitted ? SuccessBanner({ selected }) : null
  );

  const header = createElement(
    "div",
    { className: "card-header" },
    createElement("h1", null, "Notification Preferences"),
    createElement("p", null, "Choose how you'd like us to reach you.")
  );

  const card = createElement("div", { className: "card" }, header, form);

  const main = createElement("main", { id: "main-content" }, card);

  const skipLink = createElement(
    "a",
    { className: "skip-link", href: "#main-content" },
    "Skip to main content"
  );

  const fragment = document.createDocumentFragment();
  fragment.appendChild(skipLink);
  fragment.appendChild(main);
  return fragment;
}

/* ──────────────────────────────────────────────
   Boot
────────────────────────────────────────────── */

// DocumentFragment can't be directly appended via our render helper,
// so we handle the root render specially.
(function boot() {
  const root = document.getElementById("root");
  root.innerHTML = "";
  root.appendChild(App());

  // Re-render helper: replace root children
  const originalRender = render;
  window.__rerender = function () {
    root.innerHTML = "";
    root.appendChild(App());
  };

  // Patch setState to use the re-render helper
  const originalSetState = setState;
  Object.defineProperty(window, "setState", { value: setState });
})();

// Override setState after boot so it calls __rerender
const _setState = setState;
Object.assign(window, { setState: _setState });

// Final re-wire: patch module-level setState reference
(function patchRerender() {
  // setState is already closing over state; we just need render to call __rerender
  const root = document.getElementById("root");
  // Replace the render call in setState by reassigning render in module scope — not possible
  // with const. Use a flag instead: re-render by swapping root children directly.
  // Already handled in setState via render(App, root) which calls root.innerHTML = "" + appendChild
  // BUT App() returns a DocumentFragment. Fix: wrap fragment in a div-less approach.
  // The render() helper calls component() and appends the result — it works for Elements.
  // For DocumentFragment we need a shim. Done: render calls container.appendChild(component())
  // which works for DocumentFragment too (it moves all children in). ✓
})();
