/* ──────────────────────────────────────────────
   Lightweight React-style component system
   (No build step — runs natively in the browser)
────────────────────────────────────────────── */

// Minimal createElement / render helpers
function createElement(tag, props, ...children) {
  const el = document.createElement(tag);

  if (props) {
    for (const [key, value] of Object.entries(props)) {
      if (key === "className") {
        el.className = value;
      } else if (key === "htmlFor") {
        el.setAttribute("for", value);
      } else if (key.startsWith("aria")) {
        // ariaLabel → aria-label, ariaDescribedby → aria-describedby
        const attr = key.replace(/([A-Z])/g, (m) => `-${m.toLowerCase()}`);
        el.setAttribute(attr, value);
      } else if (key === "role" || key === "type" || key === "name" || key === "id" ||
                 key === "value" || key === "checked" || key === "disabled" ||
                 key === "tabIndex") {
        el[key] = value;
      } else if (key.startsWith("on") && typeof value === "function") {
        const event = key.slice(2).toLowerCase();
        el.addEventListener(event, value);
      } else {
        el.setAttribute(key, value);
      }
    }
  }

  for (const child of children.flat(Infinity)) {
    if (child == null || child === false) continue;
    el.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
  }

  return el;
}

function render(component, container) {
  container.innerHTML = "";
  container.appendChild(component());
}

/* ──────────────────────────────────────────────
   Data
────────────────────────────────────────────── */

const NOTIFICATION_OPTIONS = [
  { value: "email",  label: "Email",              icon: "✉️" },
  { value: "sms",    label: "SMS",                icon: "💬" },
  { value: "push",   label: "Push Notifications", icon: "🔔" },
];

/* ──────────────────────────────────────────────
   State (simple reactive store)
────────────────────────────────────────────── */

const state = {
  selected: null,
  submitted: false,
  error: false,
};

function setState(patch) {
  Object.assign(state, patch);
  render(App, document.getElementById("root"));
  // If an error was showing and a selection is now made, clear it
}

/* ──────────────────────────────────────────────
   Components
────────────────────────────────────────────── */

function RadioOption({ option, selected, onChange }) {
  const inputId = `radio-${option.value}`;
  const isChecked = selected === option.value;

  const input = createElement("input", {
    type: "radio",
    id: inputId,
    name: "notification-preference",
    value: option.value,
    checked: isChecked,
    ariaChecked: String(isChecked),
    onChange: (e) => onChange(e.target.value),
  });

  const icon = createElement("span", { className: "option-icon", ariaHidden: "true" }, option.icon);
  const label = createElement("label", { htmlFor: inputId }, option.label);

  const wrapper = createElement("div", { className: "radio-option" }, icon, input, label);

  // Make the whole card row clickable (click fires the hidden label click)
  wrapper.addEventListener("click", (e) => {
    if (e.target !== input && e.target !== label) {
      input.click();
    }
  });

  return wrapper;
}

function RadioGroup({ options, selected, onChange, errorId }) {
  const radios = options.map((option) =>
    RadioOption({ option, selected, onChange })
  );

  return createElement(
    "fieldset",
    { ariaDescribedby: errorId },
    createElement("legend", null, "How do you prefer to receive notifications?"),
    createElement("div", { className: "radio-group", role: "radiogroup" }, ...radios)
  );
}

function FormField({ options, selected, onChange, error }) {
  const hintId = "notification-hint";

  const hint = createElement(
    "p",
    {
      className: "field-hint",
      id: hintId,
      role: error ? "alert" : null,
      ariaLive: "polite",
    },
    error ? "Please select a notification preference to continue." : ""
  );

  return createElement(
    "div",
    { className: "form-field" },
    RadioGroup({ options, selected, onChange, errorId: hintId }),
    hint
  );
}

function SuccessBanner({ selected }) {
  const option = NOTIFICATION_OPTIONS.find((o) => o.value === selected);
  const label = option ? option.label : selected;

  return createElement(
    "div",
    {
      className: "success-banner visible",
      role: "status",
      ariaLive: "polite",
    },
    createElement("span", { ariaHidden: "true" }, "✅"),
    `Preference saved! You'll receive notifications via ${label}.`
  );
}

function App() {
  const { selected, submitted, error } = state;

  function handleChange(value) {
    setState({ selected: value, error: false });
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (!selected) {
      setState({ error: true });
      // Focus the first radio for keyboard users
      setTimeout(() => {
        const first = document.querySelector('input[name="notification-preference"]');
        if (first) first.focus();
      }, 0);
      return;
    }
    setState({ submitted: true, error: false });
  }

  const form = createElement(
    "form",
    { onSubmit: handleSubmit, noValidate: true, ariaLabel: "Notification preferences" },
    FormField({
      options: NOTIFICATION_OPTIONS,
      selected,
      onChange: handleChange,
      error,
    }),
    createElement(
      "button",
      {
        type: "submit",
        className: "btn-submit",
        disabled: submitted,
        ariaDisabled: submitted ? "true" : "false",
      },
      submitted ? "✓ Saved" : "Save Preference"
    ),
    submitted ? SuccessBanner({ selected }) : null
  );

  const header = createElement(
    "div",
    { className: "card-header" },
    createElement("h1", null, "Notification Preferences"),
    createElement("p", null, "Choose how you'd like us to reach you.")
  );

  const card = createElement("div", { className: "card" }, header, form);

  const main = createElement("main", { id: "main-content" }, card);

  const skipLink = createElement(
    "a",
    { className: "skip-link", href: "#main-content" },
    "Skip to main content"
  );

  const fragment = document.createDocumentFragment();
  fragment.appendChild(skipLink);
  fragment.appendChild(main);
  return fragment;
}

/* ──────────────────────────────────────────────
   Boot
   App() returns a DocumentFragment; appendChild
   correctly moves all its children into root.
────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", () => {
  render(App, document.getElementById("root"));
});
